import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.Cj77QY92.js";const g=JSON.parse('{"title":"Terraform on AWS: Provisioning an EC2 Instance Step by Step","description":"A hands-on log of installing Terraform, reading a main.tf file, applying it to AWS, moving hard-coded values into variables and modules, and finally tearing everything down.","frontmatter":{"title":"Terraform on AWS: Provisioning an EC2 Instance Step by Step","date":"2026-09-25T00:00:00.000Z","tags":["Terraform","AWS","DevOps"],"readingMinutes":12,"description":"A hands-on log of installing Terraform, reading a main.tf file, applying it to AWS, moving hard-coded values into variables and modules, and finally tearing everything down."},"headers":[],"relativePath":"posts/terraform-aws-ec2-setup.md","filePath":"posts/terraform-aws-ec2-setup.md","lastUpdated":1791828061000}'),n={name:"posts/terraform-aws-ec2-setup.md"};function o(r,e,l,p,h,d){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="terraform-on-aws-provisioning-an-ec2-instance-step-by-step" tabindex="-1">Terraform on AWS: Provisioning an EC2 Instance Step by Step <a class="header-anchor" href="#terraform-on-aws-provisioning-an-ec2-instance-step-by-step" aria-label="Permalink to &quot;Terraform on AWS: Provisioning an EC2 Instance Step by Step&quot;">​</a></h1><p class="xq-lead"> My notes from working through a Terraform-on-AWS exercise: installing the CLI, reading a <code>main.tf</code>, applying it, and then cleaning up after myself. </p><h2 id="_1-installation" tabindex="-1">1. Installation <a class="header-anchor" href="#_1-installation" aria-label="Permalink to &quot;1. Installation&quot;">​</a></h2><p>Clone the project and install Terraform.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/1.png" alt="Installing Terraform" loading="lazy"></p><p>Open cmd as administrator and run <code>echo %PATH%</code> to see which folders Terraform can run from.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/2.png" alt="Checking PATH" loading="lazy"></p><p>It failed to run, so Go has to be installed as well: <a href="https://go.dev/dl/" target="_blank" rel="noreferrer">https://go.dev/dl/</a>.</p><p>After installation the environment variables need to be configured.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/3%20(2).png" alt="Go download page" loading="lazy"></p><p>Open <strong>Environment Variables</strong> and add Go to <code>PATH</code>.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/5.png" alt="Adding Go to PATH" loading="lazy"></p><p>Click OK, apply the change, and restart cmd.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011405375.png" alt="Terraform installed successfully" loading="lazy"></p><p>Installed successfully.</p><h3 id="getting-credentials" tabindex="-1">Getting credentials <a class="header-anchor" href="#getting-credentials" aria-label="Permalink to &quot;Getting credentials&quot;">​</a></h3><p>Run <code>aws login</code> to obtain credentials.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011419799.png" alt="Running aws login" loading="lazy"></p><p>As shown above, the last line is the credentials.</p><h2 id="_2-the-terraform-files" tabindex="-1">2. The Terraform files <a class="header-anchor" href="#_2-the-terraform-files" aria-label="Permalink to &quot;2. The Terraform files&quot;">​</a></h2><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011212879.png" alt="Terraform Registry" loading="lazy"></p><p>HashiCorp maintains the Terraform Registry, so providers can be taken from the public registry.</p><ul><li>The <code>source</code> is written as <code>[hostname (optional)/]namespace/provider</code>.</li><li>The full form is <code>registry.terraform.io/hashicorp/aws</code>, but since the hostname defaults to <code>registry.terraform.io</code> it can be omitted.</li><li>If <code>version</code> is left empty, the newest version is selected automatically.</li><li><code>required_version</code> is the Terraform version.</li></ul><p>The guide hands you a <code>main.tf</code>; here is what each part of it does.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011436838.png" alt="main.tf" loading="lazy"></p><h3 id="provider" tabindex="-1">Provider <a class="header-anchor" href="#provider" aria-label="Permalink to &quot;Provider&quot;">​</a></h3><p>A provider configures the API of a cloud platform, and the <code>provider</code> block is where a provider is configured. There can be several provider blocks, for example to configure more than one provider.</p><p>The AWS provider authenticates the same way as the AWS CLI, which needs <code>AWS_ACCESS_KEY_ID</code> and <code>AWS_SECRET_ACCESS_KEY</code>. There are three ways to authenticate:</p><ol><li><strong>Directly in the provider block</strong> — highest priority.</li><li><strong>Through environment variables</strong>, for example in Windows cmd: <code>set AWS_ACCESS_KEY_ID=XXX</code>.</li><li><strong>Automatically.</strong> Once <code>aws login</code> has been run, the credentials are already on the machine; check them with <code>aws configure list</code> in the cmd session that is logged in to AWS.</li></ol><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011455239.png" alt="Authentication methods" loading="lazy"></p><h3 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h3><p>A <code>data</code> block does not configure anything — it reads from the provider. Everything in it is a query, resolved at run time, so nothing is visible before Terraform runs.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011516180.png" alt="data block" loading="lazy"></p><h3 id="resource" tabindex="-1">Resource <a class="header-anchor" href="#resource" aria-label="Permalink to &quot;Resource&quot;">​</a></h3><p>Which arguments a resource takes is decided by the people who wrote the provider (AWS, Azure, ...).</p><p>The first line of a resource declares <code>aws_instance</code> <code>&quot;app_server&quot;</code> — the resource type and the local name. Together they form <code>aws_instance.app_server</code>, which resolves to the instance id.</p><ul><li><code>ami</code> selects the image.</li><li><code>instance_type</code> is hard-coded to <code>t2.micro</code>, which fits inside the AWS free tier.</li><li><code>tags</code> sets the name of the EC2 instance.</li></ul><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011531069.png" alt="resource block" loading="lazy"></p><h2 id="_3-applying-the-configuration" tabindex="-1">3. Applying the configuration <a class="header-anchor" href="#_3-applying-the-configuration" aria-label="Permalink to &quot;3. Applying the configuration&quot;">​</a></h2><p>Format the files the way Terraform recommends:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fmt</span></span></code></pre></div><p>If the files do not match the style, they are rewritten.</p><p>Initialise the working directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011548756.png" alt="terraform init" loading="lazy"></p><p>Validate the configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span></code></pre></div><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011602262.png" alt="terraform validate" loading="lazy"></p><p>The configuration is valid.</p><p>Terraform applies infrastructure in two steps: it prints an execution plan and waits for approval, then uses the provider to make the changes. That workflow lets you inspect anything unexpected. Run <code>terraform apply</code> — Terraform prints the plan and asks you to confirm.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011631198.png" alt="terraform apply and an error" loading="lazy"></p><p>An error: after a reboot the <code>aws login</code> session is no longer valid. Open cmd again, run <code>aws login</code>, and try once more.</p><p>It failed again — <code>aws login</code> only applies to the AWS CLI and the SDKs.</p><h3 id="working-around-the-expiring-session" tabindex="-1">Working around the expiring session <a class="header-anchor" href="#working-around-the-expiring-session" aria-label="Permalink to &quot;Working around the expiring session&quot;">​</a></h3><p>Run <code>aws configure export-credentials --format env</code> to get the credentials.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011643667.png" alt="Exporting credentials" loading="lazy"></p><p>Then put them into environment variables:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AWS_ACCESS_KEY_ID </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_access_key&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AWS_SECRET_ACCESS_KEY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_secret_key&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AWS_SESSION_TOKEN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_session_token&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AWS_DEFAULT_REGION </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;us-east-2&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">They expire</p><p>Be quick about it. Honestly, this authentication dance is a real pain.</p></div><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011656285.png" alt="Running terraform apply" loading="lazy"></p><p>Type <code>yes</code>.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011707974.png" alt="Instance created" loading="lazy"></p><p>Created successfully — AWS even sent an email about it. The new instance can be found in the EC2 console.</p><h3 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h3><p>After the write, Terraform creates a <code>terraform.tfstate</code> file that it uses to manage the lifecycle.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> state</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>…lists the resources Terraform is managing.</p><h2 id="_4-changing-the-configuration" tabindex="-1">4. Changing the configuration <a class="header-anchor" href="#_4-changing-the-configuration" aria-label="Permalink to &quot;4. Changing the configuration&quot;">​</a></h2><p>Create <code>variables.tf</code> so that values can be changed there instead of inside <code>main.tf</code>.</p><p><strong>variables.tf</strong></p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011724833.png" alt="variables.tf" loading="lazy"></p><p>Creating <code>output.tf</code> as well is recommended, so that more information can be surfaced.</p><p><strong>output.tf</strong></p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011736235.png" alt="output.tf" loading="lazy"></p><p>Those two values follow the resource in <code>main.tf</code>; to output something else, the values have to be changed.</p><p>Back to the point: the resource values in <code>main.tf</code> are hard-coded, so now that <code>variables.tf</code> exists, the resource has to reference the variables instead.</p><p><strong>main.tf</strong></p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011748350.png" alt="Referencing variables from main.tf" loading="lazy"></p><p>This way the values come from the variables.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -var</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> instance_type=t2.large</span></span></code></pre></div><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011800477.png" alt="Overriding a variable" loading="lazy"></p><p>The variable was overridden successfully.</p><h3 id="module" tabindex="-1">Module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;Module&quot;">​</a></h3><p>A module is a reusable set of configurations that can manage multiple resources and data sources. Ready-made modules live on the <a href="https://registry.terraform.io/browse/modules" target="_blank" rel="noreferrer">Terraform Registry</a>, or you can write your own.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011814413.png" alt="Adding a module" loading="lazy"></p><p>After putting the module into <code>main.tf</code> the editor warns, because <code>terraform init</code> has not been run yet. Run it in the terminal and the warning disappears.</p><p>Then add these to the resource:</p><div class="language-hcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vpc_security_group_ids</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vpc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_security_group_id]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subnet_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">              =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vpc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">private_subnets[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The purpose is to place the EC2 instance in the first private subnet of the new VPC, using the VPC&#39;s default security group.</p><p>Run <code>terraform init</code> again every time the configuration changes, then run <code>terraform apply</code>.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011829187.png" alt="Applying with the module" loading="lazy"></p><p>It succeeded, but <code>public_ip</code> is empty — which is normal, because the instance now sits in a private subnet.</p><h2 id="_5-removing-everything" tabindex="-1">5. Removing everything <a class="header-anchor" href="#_5-removing-everything" aria-label="Permalink to &quot;5. Removing everything&quot;">​</a></h2><p>The resource and the output have to be deleted (or commented out) to remove the EC2 instance; after that, tell Terraform about it with <code>terraform apply</code>.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/20260927011841977.png" alt="Removing the resource" loading="lazy"></p><p>Then run <code>terraform destroy</code> to remove the working directory state and the resources in the cloud.</p><p>To sum up: <code>terraform apply</code> removes the resources you asked it to remove, while <code>terraform destroy</code> tears down everything the configuration created — the local files stay.</p>`,97)])])}const m=a(n,[["render",o]]);export{g as __pageData,m as default};
